// First-species counterpoint: a cantus firmus and a note-against-note line
// above or below it, generated by depth-first search under the classroom
// rules. Pure (depends on Theory); browser global or Node module.
(function (root) {
  'use strict';

  var T = typeof module !== 'undefined' && module.exports ? require('./theory.js') : root.Theory;

  function rngPick(arr, rnd) { return arr[Math.floor(rnd() * arr.length)]; }
  function shuffle(arr, rnd) {
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(rnd() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
    return a;
  }

  function noteAt(k, tonic, off) {
    var n = T.fromStep(T.step(tonic) + off, 0);
    n.acc = T.sigAcc(T.fifths(k), n.l);
    return n;
  }

  // Cantus firmus as diatonic offsets from the tonic: starts and ends on do,
  // re before the end, mostly steps, one high point, range within a 6th.
  function makeCantus(len, rnd) {
    rnd = rnd || Math.random;
    for (var tries = 0; tries < 2000; tries++) {
      var seq = [0];
      var ok = true;
      while (seq.length < len - 2) {
        var cur = seq[seq.length - 1];
        var prevMove = seq.length > 1 ? cur - seq[seq.length - 2] : 0;
        var moves = Math.abs(prevMove) >= 3 ? [prevMove > 0 ? -1 : 1] // recover from a leap by step
          : [-1, -1, 1, 1, -2, 2, 3, -3, 4];
        var opts = moves.map(function (m) { return cur + m; }).filter(function (o) { return o >= -2 && o <= 5 && o !== cur; });
        if (!opts.length) { ok = false; break; }
        seq.push(rngPick(opts, rnd));
      }
      if (!ok) continue;
      var last = seq[seq.length - 1];
      if (Math.abs(last - 1) > 2 || last === 1) continue; // approach re by step or third
      seq.push(1, 0);
      var hi = Math.max.apply(null, seq);
      if (seq.filter(function (x) { return x === hi; }).length !== 1) continue; // one climax
      if (hi < 2) continue;
      return seq;
    }
    return [0, 1, 2, 1, 0].concat([]).slice(0, len - 2).concat([1, 0]);
  }

  var GOOD_VERTICAL = { P1: 1, m3: 1, M3: 1, P5: 1, m6: 1, M6: 1, P8: 1, m10: 1, M10: 1, P12: 1 };
  function perfectClass(semis) { var m = ((semis % 12) + 12) % 12; return m === 0 || m === 7 ? m : -1; }

  // Why a counterpoint note is not allowed here (null when it's fine).
  function violation(cf, cp, i, above, len) {
    var lo = above ? cf[i] : cp[i], hi = above ? cp[i] : cf[i];
    var iv = T.interval(lo, hi);
    if (T.midi(hi) < T.midi(lo)) return 'voices crossed';
    if (!GOOD_VERTICAL[iv.id]) return 'dissonance or bad interval ' + iv.id;
    if (T.midi(hi) - T.midi(lo) > 16) return 'too far apart';
    var first = i === 0, last = i === len - 1;
    if (first && !(iv.id === 'P1' || iv.id === 'P8' || (above && iv.id === 'P5') || iv.id === 'P12')) return 'must start on a perfect consonance';
    if (last && !(iv.id === 'P1' || iv.id === 'P8')) return 'must end on a unison or octave';
    if (!first && !last && iv.id === 'P1') return 'unison in the middle';
    if (i > 0) {
      var a0 = T.midi(cf[i - 1]), b0 = T.midi(cp[i - 1]), a1 = T.midi(cf[i]), b1 = T.midi(cp[i]);
      var mv = T.interval(cp[i - 1], cp[i]);
      if (mv.id[0] === 'A' || mv.id[0] === 'd') return 'augmented/diminished leap';
      if (mv.size > 4 && mv.size !== 7) return 'leap too big';
      if (a1 === a0 && b1 === b0) return 'both voices repeat';
      var p0 = perfectClass(Math.abs(b0 - a0)), p1 = perfectClass(Math.abs(b1 - a1));
      var similar = (a1 - a0) * (b1 - b0) > 0;
      if (p1 >= 0 && p0 === p1 && (a1 !== a0 || b1 !== b0)) return 'parallel perfect interval';
      if (p1 >= 0 && similar) {
        // hidden 5th/8ve: similar motion into a perfect interval with a leap on top
        var top0 = above ? b0 : a0, top1 = above ? b1 : a1;
        if (Math.abs(top1 - top0) > 2) return 'hidden 5th/8ve';
      }
      if (i > 1) {
        var prevMv = T.step(cp[i - 1]) - T.step(cp[i - 2]);
        var mvSteps = T.step(cp[i]) - T.step(cp[i - 1]);
        if (Math.abs(prevMv) >= 3 && (mvSteps * prevMv > 0 || Math.abs(mvSteps) > 2)) return 'leap not recovered';
        if (b1 === b0 && T.midi(cp[i - 2]) === b0) return 'three repeated notes';
      }
    }
    return null;
  }

  // Counterpoint against spelled cantus notes. above: CP above the CF.
  function makeCounterpoint(k, cf, above, rnd) {
    rnd = rnd || Math.random;
    var len = cf.length;
    var tonic = T.note(k.tonic.l, k.tonic.acc, cf[0].oct);
    while (T.step(tonic) > T.step(cf[0])) tonic.oct--;
    var cp = [];
    var nodes = 0;
    function candidates(i) {
      var base = T.step(cf[i]) - T.step(tonic);
      var ds = [];
      for (var d = 0; d <= 9; d++) ds.push(above ? base + d : base - d);
      // prefer steps from the previous note, then small leaps
      if (i > 0) {
        var prevOff = T.step(cp[i - 1]) - T.step(tonic);
        ds = shuffle(ds, rnd).sort(function (x, y) {
          var mx = Math.abs(x - prevOff), my = Math.abs(y - prevOff);
          var wx = mx === 1 ? 0 : mx === 2 ? 1 : mx === 0 ? 3 : 2, wy = my === 1 ? 0 : my === 2 ? 1 : my === 0 ? 3 : 2;
          return wx - wy + (rnd() - 0.5) * 1.5;
        });
      } else {
        ds = shuffle(ds, rnd);
      }
      // the penultimate note is the leading tone (ti), resolving to do
      if (i === len - 2) ds = ds.filter(function (o) { return T.mod(o, 7) === 6; });
      return ds.map(function (o) { return noteAt(k, tonic, o); });
    }
    function dfs(i) {
      if (++nodes > 20000) return false;
      if (i === len) return true;
      var cs = candidates(i);
      for (var c = 0; c < cs.length; c++) {
        cp[i] = cs[c];
        if (!violation(cf, cp, i, above, len) && dfs(i + 1)) return true;
      }
      cp.length = i;
      return false;
    }
    return dfs(0) ? cp.slice() : null;
  }

  // A full two-part exercise in key k: { cf, cp, upper, lower } spelled.
  // cfTonic: where the cantus sits (a placed tonic note).
  function makeDuet(k, len, cfAbove, cfTonic, rnd) {
    rnd = rnd || Math.random;
    for (var tries = 0; tries < 60; tries++) {
      var offs = makeCantus(len, rnd);
      var cf = offs.map(function (o) { return noteAt(k, cfTonic, o); });
      // the spelled cantus can't leap an augmented/diminished interval either (ti-fa)
      if (cf.some(function (n, i) { return i > 0 && /^[Ad]/.test(T.interval(cf[i - 1], n).id); })) continue;
      var cp = makeCounterpoint(k, cf, !cfAbove, rnd);
      if (cp) return { cf: cf, cp: cp, upper: cfAbove ? cf : cp, lower: cfAbove ? cp : cf };
    }
    return null;
  }

  var api = { makeCantus: makeCantus, makeCounterpoint: makeCounterpoint, makeDuet: makeDuet, violation: violation, noteAt: noteAt };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.Counterpoint = api;
})(this);
